/* v25 THE PHONE IS THE SCENE. Founder playtest 2026-09-24: "on phone I can't even see the
   whole post I'm reviewing." studio-fingers-play measured it: the L1 post 64% visible on both
   375x667 and 393x852, Boost reachable while the post it acts on was not. Now the feed is fitted
   to the screen (fitFeed), the phone runs the column's full width, the rank strip steps aside on
   short screens (the promotion screen carries rank), and Next waits beside Boost, not below the
   fold as a greyed second primary. */
#sc-train .train-phone{max-width:340px}
#sc-train .fc-media{height:120px}
#sc-train .act-zone{display:flex;gap:10px;align-items:stretch}
#sc-train .act-zone>*{flex:1 1 0;min-width:0}
#sc-train .act-zone .big-btn.advance{margin:0;max-width:none;width:auto}
#sc-train .advance:not(.ready){display:none}
@media (max-height:900px){#sc-train .ranks{display:none}}

/* ── About the photos (v24) ── */
.about-link{display:inline-block;margin-top:14px;min-height:48px;padding:10px 16px;background:transparent;border:1px solid var(--edge);border-radius:14px;color:var(--ink);font:inherit;font-size:16px;font-weight:700;cursor:pointer}
.about-link:hover,.about-link:focus-visible{border-color:var(--phos)}
.about-h{color:var(--ink);font-size:clamp(22px,6vw,28px);font-weight:900;margin:8px 0 10px}
.about-p{color:var(--ink);font-size:18px;line-height:1.5;text-align:left;max-width:34ch;margin:10px auto;text-wrap:pretty}
.about-list{list-style:none;padding:0;margin:16px auto;max-width:420px;text-align:left}
.about-list li{display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-top:1px solid var(--edge);color:var(--ink);font-size:18px;line-height:1.4}
.about-list img{width:96px;height:64px;object-fit:cover;border-radius:8px;flex:none}
.about-list a{color:var(--ink);text-decoration:underline;display:inline-block;min-height:44px;line-height:44px}
.about-list b{font-weight:800}

// ── FEED PHOTOS (v24). Real, ordinary photographs from Wikimedia Commons, open-licensed.
//    Founder ruling 2026-09-23: the ordinary, attributed off-post (About the photos).
//    Horvath seat: pleasant-neutral, never eerie. Sources + licenses: art-department/flok-feed/CREDITS.md
