const BODY_IMG=['basil','loaf','trail','bed','cassette','coffees','sunset','boxes','pizza','laptop'];
const R1_IMG=['creek','trail','fog','sunset','night','creek','trail','night','night','creek'];
function media(k){return '<img class="fc-media" src="'+IMG[k]+'" alt="'+ALT[k]+'" data-art="legal-photo: Wikimedia Commons, see About the photos" loading="lazy" decoding="async">';}
function r1img(body){var i=R1_POSTS.indexOf(body);return i<0?(body.indexOf('opened the app')===0?'bed':'night'):R1_IMG[i];}

// v25: an empty bell is not a button. The naive-player pass pressed it on every lever
// and nothing happened - a dead control the eye reads as live.
const live=n>0&&LEVERS[step]&&LEVERS[step].type==='release';
b.setAttribute('aria-disabled',live?'false':'true');b.tabIndex=live?0:-1;b.style.pointerEvents=live?'':'none';

// v25: size the feed so brief, phone and the action all fit one phone screen, with the
// post you are judging whole. If the screen is too short for that, the post wins and the
// page scrolls - never the other way round.
function fitFeed(){
  const s=document.getElementById('sc-train');if(!s||!s.classList.contains('on'))return;
  const f=document.getElementById('feed'),br=document.getElementById('brief'),az=document.getElementById('actZone');
  const cur=f.getBoundingClientRect().height;
  const span=az.getBoundingClientRect().bottom-br.getBoundingClientRect().top;
  const L=LEVERS[step];
  // the focus decides the floor: the whole post (L1, L4), the whole message list (L5);
  // on the streak lever the banner is the focus, so the post below it may run under the fold.
  document.getElementById('feedMore').hidden=(L.type==='send'||L.type==='flip');
  const card=f.querySelector('.dm,.feed-card');
  const need=L.type==='send'?120:(card?Math.ceil(card.getBoundingClientRect().height)+20:240);
  let h=cur+(window.innerHeight-18-span);
  h=Math.max(need,Math.min(h,Math.max(need,window.innerHeight*0.62)));
  f.style.height=Math.round(h)+'px';
  window.scrollTo({top:Math.max(0,br.getBoundingClientRect().top+window.scrollY-6),behavior:'auto'});
}
window.addEventListener('resize',function(){requestAnimationFrame(fitFeed);});

const SCREENS=['hire','train','rank','flip-seat','about'];
let aboutBack='hire';
function openAbout(from){
  aboutBack=from;
  const ul=document.getElementById('aboutList');
  if(!ul.childElementCount){
    ul.innerHTML=CREDITS.map(function(c){
      return '<li><img src="'+IMG[c[0]]+'" alt=""><span><b>'+ALT[c[0]]+'</b><br>'+c[1]+' &middot; '+c[2]+'<br><a href="https://commons.wikimedia.org/wiki/File:'+c[3]+'">Wikimedia Commons page</a></span></li>';
    }).join('');
  }
  go('about');
}
